func readStopCommitEvidence(t *testing.T, db *sql.DB, runID string) stopCommitEvidence {
	t.Helper()
	var e stopCommitEvidence
	if err := db.QueryRow(`SELECT r.status,COALESCE(c.control_status,'') FROM runs r LEFT JOIN run_control_state c ON c.run_id=r.run_id WHERE r.run_id=$1`, runID).Scan(&e.status, &e.control); err != nil {
		t.Fatal(err)
	}
	for query, target := range map[string]*int{`SELECT COUNT(*) FROM events WHERE run_id=$1`: &e.events, `SELECT COUNT(*) FROM fan_out_intents WHERE run_id=$1 AND status='canceled'`: &e.canceled, `SELECT COUNT(*) FROM event_deliveries WHERE run_id=$1 AND status IN ('pending','processing','retrying')`: &e.pending, `SELECT COUNT(*) FROM fan_out_outcomes WHERE run_id=$1`: &e.outcomes, `SELECT COUNT(*) FROM run_fork_revisions WHERE run_id=$1`: &e.revisions} {
		if err := db.QueryRow(query, runID).Scan(target); err != nil {
			t.Fatal(err)
		}
	}
	return e
}

